import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderLookup;
import java.time.Instant;
import org.junit.jupiter.api.Test;

class OrderServiceLatestTest {

    private final OrderService service = new OrderService(new OrderRepository());

    @Test
    void aCustomerWithNoOrdersHasNoLatestOrder() {
        OrderLookup lookup = service.latestForCustomer("c-1");

        assertFalse(lookup.found());
        assertNull(lookup.order());
    }

    @Test
    void theOrderPlacedLastIsReturned() {
        service.place("c-1", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z"));
        String latest = service.place("c-1", Money.pln(300), Instant.parse("2026-10-03T10:00:00Z"));
        service.place("c-1", Money.pln(200), Instant.parse("2026-10-02T10:00:00Z"));

        OrderLookup lookup = service.latestForCustomer("c-1");

        assertTrue(lookup.found());
        assertEquals(latest, lookup.order().id());
        assertEquals("c-1", lookup.order().customerId());
        assertEquals(Money.pln(300), lookup.order().total());
    }

    @Test
    void otherCustomersOrdersAreIgnored() {
        String mine = service.place("c-1", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z"));
        service.place("c-2", Money.pln(999), Instant.parse("2026-10-05T10:00:00Z"));

        assertEquals(mine, service.latestForCustomer("c-1").order().id());
    }

    @Test
    void customerWithOnlyOtherOrdersHasNoLatestOrder() {
        service.place("c-2", Money.pln(999), Instant.parse("2026-10-05T10:00:00Z"));

        assertFalse(service.latestForCustomer("c-1").found());
    }
}
